#!/usr/bin/env node
import { execFileSync } from 'node:child_process';
import { readFileSync, writeFileSync } from 'node:fs';

const src = process.argv[2];
if (!src) {
  console.error('usage: node scripts/generate-filter-table.mjs <openapi.json path or URL>');
  process.exit(1);
}

const text = /^https?:\/\//.test(src) ? await (await fetch(src)).text() : readFileSync(src, 'utf8');
const grammar = JSON.parse(text)['x-profound-filter-grammar'];
if (!grammar) {
  console.error(`spec at ${src} has no x-profound-filter-grammar extension`);
  process.exit(1);
}

const lines = [
  '// Generated by scripts/generate-filter-table.mjs from the x-profound-filter-grammar',
  '// extension of the Profound OpenAPI spec. Do not edit by hand.',
  '',
  `export const MAX_DEPTH = ${grammar.max_depth};`,
  '',
  'export const FIELD_TABLE = {',
];
for (const [name, { layer, ops }] of Object.entries(grammar.fields)) {
  lines.push(`  ${name}: {`, `    layer: '${layer}',`, '    ops: [');
  for (const op of ops) lines.push(`      '${op}',`);
  lines.push('    ],', '  },');
}
lines.push('} as const;', '');

const out = new URL('../src/lib/filter-table.ts', import.meta.url);
writeFileSync(out, lines.join('\n'));
try {
  execFileSync('npx', ['--yes', '@biomejs/biome@2.5.7', 'format', '--write', out.pathname], {
    stdio: 'pipe',
  });
} catch {
  console.warn('biome format failed; run it manually before committing');
}
console.log(`wrote ${out.pathname}`);
